 styling immediately reflects the current\n  // toolbar state. The classes are removed after the toolbar completes\n  // initialization.\n  const classesToAdd = [\'toolbar-loading\', \'toolbar-anti-flicker\'];\n  if (toolbarState) {\n    const {\n      orientation,\n      hasActiveTab,\n      isFixed,\n      activeTray,\n      activeTabId,\n      isOriented,\n      userButtonMinWidth\n    } = toolbarState;\n\n    classesToAdd.push(\n      orientation ? `toolbar-` + orientation + `` : \'toolbar-horizontal\',\n    );\n    if (hasActiveTab !== false) {\n      classesToAdd.push(\'toolbar-tray-open\');\n    }\n    if (isFixed) {\n      classesToAdd.push(\'toolbar-fixed\');\n    }\n    if (isOriented) {\n      classesToAdd.push(\'toolbar-oriented\');\n    }\n\n    if (activeTray) {\n      // These styles are added so the active tab/tray styles are present\n      // immediately instead of \"flickering\" on as the toolbar initializes. In\n      // instances where a tray is lazy loaded, these styles facilitate the\n      // lazy loaded tray appearing gracefully and without reflow.\n      const styleContent = `\n      .toolbar-loading #` + activeTabId + ` {\n        background-image: linear-gradient(rgba(255, 255, 255, 0.25) 20%, transparent 200%);\n      }\n      .toolbar-loading #` + activeTabId + `-tray {\n        display: block; box-shadow: -1px 0 5px 2px rgb(0 0 0 / 33%);\n        border-right: 1px solid #aaa; background-color: #f5f5f5;\n        z-index: 0;\n      }\n      .toolbar-loading.toolbar-vertical.toolbar-tray-open #` + activeTabId + `-tray {\n        width: 15rem; height: 100vh;\n      }\n     .toolbar-loading.toolbar-horizontal :not(#` + activeTray + `) > .toolbar-lining {opacity: 0}`;\n\n      const style = document.createElement(\'style\');\n      style.textContent = styleContent;\n      style.setAttribute(\'data-toolbar-anti-flicker-loading\', true);\n      document.querySelector(\'head\').appendChild(style);\n\n      if (userButtonMinWidth) {\n        const userButtonStyle = document.createElement(\'style\');\n        userButtonStyle.textContent = `#toolbar-item-user {min-width: ` + userButtonMinWidth +`px;}`\n        document.querySelector(\'head\').appendChild(userButtonStyle);\n      }\n    }\n  }\n  document.querySelector(\'html\').classList.add(...classesToAdd);\n})();\";}}i:1;s:15:\"anti_flicker_js\";}}s:7:\"library\";a:18:{i:0;s:34:\"contextual/drupal.contextual-links\";i:1;s:11:\"system/base\";i:2;s:15:\"bootstrap/theme\";i:3;s:19:\"custom_theme/global\";i:4;s:23:\"core/drupal.active-link\";i:5;s:17:\"bootstrap/popover\";i:6;s:17:\"bootstrap/tooltip\";i:7;s:15:\"toolbar/toolbar\";i:8;s:19:\"devel/devel-toolbar\";i:9;s:27:\"admin_toolbar_search/search\";i:10;s:22:\"user/drupal.user.icons\";i:11;s:9:\"tour/tour\";i:12;s:36:\"contextual/drupal.contextual-toolbar\";i:13;s:32:\"admin_toolbar_tools/toolbar.icon\";i:14;s:24:\"shortcut/drupal.shortcut\";i:15;s:26:\"admin_toolbar/toolbar.tree\";i:16;s:38:\"admin_toolbar/toolbar.tree.hoverintent\";i:17;s:27:\"toolbar/toolbar.escapeAdmin\";}s:14:\"html_head_link\";a:1:{i:0;a:1:{i:0;a:3:{s:3:\"rel\";s:4:\"icon\";s:4:\"href\";s:22:\"/core/misc/favicon.ico\";s:4:\"type\";s:24:\"image/vnd.microsoft.icon\";}}}s:37:\"html_response_attachment_placeholders\";a:4:{s:6:\"styles\";s:100:\"<css-placeholder token=\"Zl7AGWA7ouB5TXFzH6wTeJkp_DKOm16upO2_I90sTx4S2lLXMmJKlilrSEW8rUnH7_BOSqvGhA\">\";s:7:\"scripts\";s:99:\"<js-placeholder token=\"Zl7AGWA7ouB5TXFzH6wTeJkp_DKOm16upO2_I90sTx4S2lLXMmJKlilrSEW8rUnH7_BOSqvGhA\">\";s:14:\"scripts_bottom\";s:106:\"<js-bottom-placeholder token=\"Zl7AGWA7ouB5TXFzH6wTeJkp_DKOm16upO2_I90sTx4S2lLXMmJKlilrSEW8rUnH7_BOSqvGhA\">\";s:4:\"head\";s:101:\"<head-placeholder token=\"Zl7AGWA7ouB5TXFzH6wTeJkp_DKOm16upO2_I90sTx4S2lLXMmJKlilrSEW8rUnH7_BOSqvGhA\">\";}s:14:\"drupalSettings\";a:3:{s:9:\"bootstrap\";a:27:{s:28:\"forms_has_error_value_toggle\";i:1;s:15:\"modal_animation\";i:1;s:14:\"modal_backdrop\";s:4:\"true\";s:17:\"modal_focus_input\";i:1;s:14:\"mod