oolbar completes\n  // initialization.\n  const classesToAdd = [\'toolbar-loading\', \'toolbar-anti-flicker\'];\n  if (toolbarState) {\n    const {\n      orientation,\n      hasActiveTab,\n      isFixed,\n      activeTray,\n      activeTabId,\n      isOriented,\n      userButtonMinWidth\n    } = toolbarState;\n\n    classesToAdd.push(\n      orientation ? `toolbar-` + orientation + `` : \'toolbar-horizontal\',\n    );\n    if (hasActiveTab !== false) {\n      classesToAdd.push(\'toolbar-tray-open\');\n    }\n    if (isFixed) {\n      classesToAdd.push(\'toolbar-fixed\');\n    }\n    if (isOriented) {\n      classesToAdd.push(\'toolbar-oriented\');\n    }\n\n    if (activeTray) {\n      // These styles are added so the active tab/tray styles are present\n      // immediately instead of \"flickering\" on as the toolbar initializes. In\n      // instances where a tray is lazy loaded, these styles facilitate the\n      // lazy loaded tray appearing gracefully and without reflow.\n      const styleContent = `\n      .toolbar-loading #` + activeTabId + ` {\n        background-image: linear-gradient(rgba(255, 255, 255, 0.25) 20%, transparent 200%);\n      }\n      .toolbar-loading #` + activeTabId + `-tray {\n        display: block; box-shadow: -1px 0 5px 2px rgb(0 0 0 / 33%);\n        border-right: 1px solid #aaa; background-color: #f5f5f5;\n        z-index: 0;\n      }\n      .toolbar-loading.toolbar-vertical.toolbar-tray-open #` + activeTabId + `-tray {\n        width: 15rem; height: 100vh;\n      }\n     .toolbar-loading.toolbar-horizontal :not(#` + activeTray + `) > .toolbar-lining {opacity: 0}`;\n\n      const style = document.createElement(\'style\');\n      style.textContent = styleContent;\n      style.setAttribute(\'data-toolbar-anti-flicker-loading\', true);\n      document.querySelector(\'head\').appendChild(style);\n\n      if (userButtonMinWidth) {\n        const userButtonStyle = document.createElement(\'style\');\n        userButtonStyle.textContent = `#toolbar-item-user {min-width: ` + userButtonMinWidth +`px;}`\n        document.querySelector(\'head\').appendChild(userButtonStyle);\n      }\n    }\n  }\n  document.querySelector(\'html\').classList.add(...classesToAdd);\n})();\";}}i:1;s:15:\"anti_flicker_js\";}}s:12:\"placeholders\";a:2:{s:55:\"form_action_p_pvdeGsVG5zNF_XLGPTvYSKCf43t8qZYSwcfZl2uzM\";a:1:{s:13:\"#lazy_builder\";a:2:{i:0;s:40:\"form_builder:renderPlaceholderFormAction\";i:1;a:0:{}}}s:190:\"<drupal-render-placeholder callback=\"Drupal\\Core\\Render\\Element\\StatusMessages::renderMessages\" arguments=\"0\" token=\"_HAdUpwWmet0TOTe2PSiJuMntExoshbm1kh2wQzzzAA\"></drupal-render-placeholder>\";a:1:{s:13:\"#lazy_builder\";a:2:{i:0;s:57:\"Drupal\\Core\\Render\\Element\\StatusMessages::renderMessages\";i:1;a:1:{i:0;N;}}}}s:14:\"drupalSettings\";a:2:{s:9:\"bootstrap\";a:27:{s:28:\"forms_has_error_value_toggle\";i:1;s:15:\"modal_animation\";i:1;s:14:\"modal_backdrop\";s:4:\"true\";s:17:\"modal_focus_input\";i:1;s:14:\"modal_keyboard\";i:1;s:17:\"modal_select_text\";i:1;s:10:\"modal_show\";i:1;s:10:\"modal_size\";s:0:\"\";s:15:\"popover_enabled\";i:1;s:17:\"popover_animation\";i:1;s:18:\"popover_auto_close\";i:1;s:17:\"popover_container\";s:4:\"body\";s:15:\"popover_content\";s:0:\"\";s:13:\"popover_delay\";s:1:\"0\";s:12:\"popover_html\";i:0;s:17:\"popover_placement\";s:5:\"right\";s:16:\"popover_selector\";s:0:\"\";s:13:\"popover_title\";s:0:\"\";s:15:\"popover_trigger\";s:5:\"click\";s:15:\"tooltip_enabled\";i:1;s:17:\"tooltip_animation\";i:1;s:17:\"tooltip_container\";s:4:\"body\";s:13:\"tooltip_delay\";s:1:\"0\";s:12:\"tooltip_html\";i:0;s:17:\"tooltip_placement\";s:9:\"auto left\";s:16:\"tooltip_selector\";s:0:\"\";s:15:\"tooltip_trigger\";s:5:\"hover\";}s:14:\"ajaxTrustedUrl\";a:1:{s:55:\"form_action_p_pvdeGsVG5zNF_XLGPTvYSKCf43t8qZYSwcfZl2uzM\";b:1;}}s:37:\"html_response_attachment_placeholders\";a:4:{s:6:\"styles\";s:100:\"<css-placeholder token=\"-oqEZG4dP6Fzj2Vv4fqKvrar-xZ_WTE_DlMM_YRS-rzSjomMw3v7PA