{\n    const {\n      orientation,\n      hasActiveTab,\n      isFixed,\n      activeTray,\n      activeTabId,\n      isOriented,\n      userButtonMinWidth\n    } = toolbarState;\n\n    classesToAdd.push(\n      orientation ? `toolbar-` + orientation + `` : \'toolbar-horizontal\',\n    );\n    if (hasActiveTab !== false) {\n      classesToAdd.push(\'toolbar-tray-open\');\n    }\n    if (isFixed) {\n      classesToAdd.push(\'toolbar-fixed\');\n    }\n    if (isOriented) {\n      classesToAdd.push(\'toolbar-oriented\');\n    }\n\n    if (activeTray) {\n      // These styles are added so the active tab/tray styles are present\n      // immediately instead of \"flickering\" on as the toolbar initializes. In\n      // instances where a tray is lazy loaded, these styles facilitate the\n      // lazy loaded tray appearing gracefully and without reflow.\n      const styleContent = `\n      .toolbar-loading #` + activeTabId + ` {\n        background-image: linear-gradient(rgba(255, 255, 255, 0.25) 20%, transparent 200%);\n      }\n      .toolbar-loading #` + activeTabId + `-tray {\n        display: block; box-shadow: -1px 0 5px 2px rgb(0 0 0 / 33%);\n        border-right: 1px solid #aaa; background-color: #f5f5f5;\n        z-index: 0;\n      }\n      .toolbar-loading.toolbar-vertical.toolbar-tray-open #` + activeTabId + `-tray {\n        width: 15rem; height: 100vh;\n      }\n     .toolbar-loading.toolbar-horizontal :not(#` + activeTray + `) > .toolbar-lining {opacity: 0}`;\n\n      const style = document.createElement(\'style\');\n      style.textContent = styleContent;\n      style.setAttribute(\'data-toolbar-anti-flicker-loading\', true);\n      document.querySelector(\'head\').appendChild(style);\n\n      if (userButtonMinWidth) {\n        const userButtonStyle = document.createElement(\'style\');\n        userButtonStyle.textContent = `#toolbar-item-user {min-width: ` + userButtonMinWidth +`px;}`\n        document.querySelector(\'head\').appendChild(userButtonStyle);\n      }\n    }\n  }\n  document.querySelector(\'html\').classList.add(...classesToAdd);\n})();\";}}i:1;s:15:\"anti_flicker_js\";}i:6;a:2:{i:0;a:2:{s:4:\"#tag\";s:4:\"link\";s:11:\"#attributes\";a:3:{s:3:\"rel\";s:4:\"icon\";s:4:\"href\";s:22:\"/core/misc/favicon.ico\";s:4:\"type\";s:24:\"image/vnd.microsoft.icon\";}}i:1;s:42:\"html_head_link:icon:/core/misc/favicon.ico\";}}s:12:\"placeholders\";a:0:{}s:14:\"drupalSettings\";a:10:{s:4:\"path\";a:7:{s:7:\"baseUrl\";s:1:\"/\";s:10:\"scriptPath\";N;s:10:\"pathPrefix\";s:0:\"\";s:11:\"currentPath\";s:20:\"user/register/author\";s:18:\"currentPathIsAdmin\";b:0;s:7:\"isFront\";b:0;s:15:\"currentLanguage\";s:2:\"en\";}s:15:\"pluralDelimiter\";s:1:\"\";s:25:\"suppressDeprecationErrors\";b:1;s:13:\"ajaxPageState\";a:3:{s:9:\"libraries\";s:165:\"bootstrap/popover,bootstrap/tooltip,core/drupal.ajax,core/drupal.collapse,core/internal.jquery.form,custom_theme/global,file/drupal.file,system/base,user/drupal.user\";s:5:\"theme\";s:12:\"custom_theme\";s:11:\"theme_token\";N;}s:14:\"ajaxTrustedUrl\";a:2:{s:55:\"form_action_p_pvdeGsVG5zNF_XLGPTvYSKCf43t8qZYSwcfZl2uzM\";b:1;s:67:\"/become-an-author?element_parents=user_picture/widget/0&ajax_form=1\";b:1;}s:9:\"bootstrap\";a:27:{s:28:\"forms_has_error_value_toggle\";i:1;s:15:\"modal_animation\";i:1;s:14:\"modal_backdrop\";s:4:\"true\";s:17:\"modal_focus_input\";i:1;s:14:\"modal_keyboard\";i:1;s:17:\"modal_select_text\";i:1;s:10:\"modal_show\";i:1;s:10:\"modal_size\";s:0:\"\";s:15:\"popover_enabled\";i:1;s:17:\"popover_animation\";i:1;s:18:\"popover_auto_close\";i:1;s:17:\"popover_container\";s:4:\"body\";s:15:\"popover_content\";s:0:\"\";s:13:\"popover_delay\";s:1:\"0\";s:12:\"popover_html\";i:0;s:17:\"popover_placement\";s:5:\"right\";s:16:\"popover_selector\";s:0:\"\";s:13:\"popover_title\";s:0:\"\";s:15:\"popover_trigger\";s:5:\"click\";s:15:\"tooltip_enabled\";i:1;s:17:\"tooltip_animation\";i:1;s:17:\"tooltip_container\";s:4:\"body\";s:13:\"tooltip_delay\";s:1:\"0\";s:12:\"tooltip_h